import base64
import gzip
import json
import frappe

DATA = ""


def execute():
	"""Restore pre-upgrade custom workspaces for Frappe v16 into Custom Workspace."""
	if not frappe.db.exists("DocType", "Custom Workspace"):
		print("Custom Workspace DocType not found, skipping.")
		return

	raw = gzip.decompress(base64.b64decode(DATA.encode("ascii")))
	docs = json.loads(raw.decode("utf-8"))

	for docdict in docs:
		ws_name = docdict.get("workspace")
		if not ws_name or not frappe.db.exists("Workspace", ws_name):
			print(f"Skipped (Workspace not found): {ws_name}")
			continue

		try:
			if frappe.db.exists("Custom Workspace", ws_name):
				cust_doc = frappe.get_doc("Custom Workspace", ws_name)
			else:
				cust_doc = frappe.new_doc("Custom Workspace")
				cust_doc.workspace = ws_name

			cust_doc.content = docdict.get("content")
			cust_doc.widgets = docdict.get("widgets")
			cust_doc.icon = docdict.get("icon")
			cust_doc.indicator_color = docdict.get("indicator_color")
			cust_doc.visibility = docdict.get("visibility") or "Visible"

			for table in ("added_roles", "removed_roles"):
				cust_doc.set(table, [])
				for r in docdict.get(table, []):
					role = r.get("role") if isinstance(r, dict) else r
					if role and frappe.db.exists("Role", role):
						cust_doc.append(table, {"role": role})

			cust_doc.save(ignore_permissions=True)
			frappe.db.commit()
			print(f"Restored Custom Workspace: {ws_name}")
		except Exception:
			frappe.db.rollback()
			frappe.log_error(title=f"Restore Custom Workspace failed: {ws_name}")
			print(f"FAILED: {ws_name} (see Error Log)")

	frappe.clear_cache()
	print("Restoration of Custom Workspaces completed.")